import{_ as e,c as t,o as r,b2 as n}from"./chunks/framework.CUhoHPxN.js";const p=JSON.parse('{"title":"C7TimePicker（C7 时间选择器）设计说明","description":"","frontmatter":{},"headers":[],"relativePath":"superpowers/specs/2026-05-07-c7-time-picker-design.md","filePath":"superpowers/specs/2026-05-07-c7-time-picker-design.md"}'),d={name:"superpowers/specs/2026-05-07-c7-time-picker-design.md"};function s(c,o,g,a,i,l){return r(),t("div",null,[...o[0]||(o[0]=[n('<h1 id="c7timepicker-c7-时间选择器-设计说明" tabindex="-1">C7TimePicker（C7 时间选择器）设计说明 <a class="header-anchor vp-link" href="#c7timepicker-c7-时间选择器-设计说明" aria-label="Permalink to &quot;C7TimePicker（C7 时间选择器）设计说明&quot;">​</a></h1><p><strong>日期</strong>：2026-05-07<br><strong>状态</strong>：已定稿（brainstorming 澄清：<strong>1B</strong> 交付含与现实现状<strong>一致性 / 差异</strong>说明；<strong>2A</strong> 仅默认 <strong><code>HH:mm:ss</code></strong>，父级显式传入则<strong>不覆盖</strong>；<strong>3A</strong> <strong><code>mergeDelimiter</code> 与 EP <code>range-separator</code> 语义分离</strong>；<strong>4A</strong> 维持 <strong><code>rangeMerge=false</code> 时不将外向 <code>string</code> 按存储串解析</strong>；<strong>5A</strong> 以本文档为设计落盘）<br><strong>依据</strong>：<code>原始需求/前端/C7时间选择器.md</code>；与 <strong><code>C7DatePicker</code></strong> 在 <strong>「计算属性 + <code>outerToInner</code> / <code>innerToOuter</code>」单数据流、<code>mergeDelimiter</code> 回退规则、默认格式注入模式」</strong> 上同构；在 <strong>范围模式下外向 <code>string</code> 是否进入拆分逻辑</strong> 上与 <strong><code>C7DatePicker</code> 有意不同</strong>（见第 8 节、第 15 节）。</p><hr><h2 id="_1-背景与目标" tabindex="-1">1. 背景与目标 <a class="header-anchor vp-link" href="#_1-背景与目标" aria-label="Permalink to &quot;1. 背景与目标&quot;">​</a></h2><p>时间选择与日期选择类似，存在 <strong><code>format</code> / <code>value-format</code></strong> 默认值约定，以及 <strong>范围模式</strong> 下「单字符串存储」与「数组」两种外向形态的切换诉求。</p><p><strong>目标</strong>：在 <strong><code>ElTimePicker</code></strong> 上封装 <strong><code>C7TimePicker</code></strong>：</p><ul><li>父级 <strong>未</strong> 传入 <strong><code>format</code> / <code>valueFormat</code>（含 <code>value-format</code>）</strong> 时，注入默认 <strong><code>HH:mm:ss</code></strong>；</li><li>在 <strong><code>is-range</code> / <code>isRange</code></strong> 为真时，通过 <strong><code>rangeMerge</code></strong> 在 <strong>合并字符串</strong>（默认逗号分隔，可用 <strong><code>mergeDelimiter</code></strong> 配置）与 <strong>EP 原生范围值</strong>（一般为二元数组）之间切换；</li><li><strong><code>change</code></strong> 载荷与 <strong><code>update:modelValue</code></strong> 外向形态一致；<strong><code>blur</code> / <code>focus</code></strong> 与 EP 一致转发。</li></ul><p><strong>验收</strong>：<strong><code>is-range</code> + <code>rangeMerge=true</code></strong> 下，外部字符串 <strong><code>&quot;08:00:00,18:00:00&quot;</code></strong> 可回显、可编辑，并按配置输出。</p><hr><h2 id="_2-实现思路-已定稿" tabindex="-1">2. 实现思路（已定稿） <a class="header-anchor vp-link" href="#_2-实现思路-已定稿" aria-label="Permalink to &quot;2. 实现思路（已定稿）&quot;">​</a></h2><p>采用与 <strong><code>C7DatePicker</code></strong> 同构的 <strong>「计算属性 + <code>outerToInner</code> / <code>innerToOuter</code>」</strong> 单数据流方案：内向仅绑定 EP 可接受的 <strong><code>model-value</code></strong>，避免 <strong><code>watch</code> 双状态</strong> 带来的循环更新风险。不采用「仅在有合并串时介入」的薄封装，以免默认格式注入与 attrs 逻辑分散。</p><hr><h2 id="_3-命名与工程位置" tabindex="-1">3. 命名与工程位置 <a class="header-anchor vp-link" href="#_3-命名与工程位置" aria-label="Permalink to &quot;3. 命名与工程位置&quot;">​</a></h2><div class="vp-table"><table><thead><tr><th>项</th><th>约定</th></tr></thead><tbody><tr><td>组件名</td><td><strong><code>C7TimePicker</code></strong></td></tr><tr><td>文件</td><td><strong><code>quick-ui/src/packages/C7TimePicker/index.vue</code></strong></td></tr><tr><td>导出</td><td>在 <strong><code>quick-ui/src/packages/index.js</code></strong> 中 <strong><code>import</code> / <code>export</code> / <code>app.component</code></strong> 与其它 C7 包一致</td></tr></tbody></table></div><hr><h2 id="_4-根节点与透传" tabindex="-1">4. 根节点与透传 <a class="header-anchor vp-link" href="#_4-根节点与透传" aria-label="Permalink to &quot;4. 根节点与透传&quot;">​</a></h2><ul><li>根节点：<strong><code>ElTimePicker</code></strong>。</li><li><strong><code>defineOptions({ name: &#39;C7TimePicker&#39;, inheritAttrs: false })</code></strong>。</li><li>根上使用经筛选的 <strong><code>v-bind</code></strong>：<strong>不得</strong>把本组件独占的 <strong><code>modelValue</code> / <code>rangeMerge</code> / <code>mergeDelimiter</code></strong> 再透传给 EP；<strong><code>model-value</code> / <code>@update:model-value</code></strong> 由包装层接管。</li><li>文档说明：<strong>除下文「显式 props」外，其余属性与 Element Plus <code>el-time-picker</code> 一致</strong>。</li><li><strong><code>visible-change</code></strong> 等其它 EP 事件：<strong>不</strong>要求在 <strong><code>defineEmits</code></strong> 中穷举；调用方可通过 <strong>模板监听</strong> 或 <strong>attrs 监听器</strong> 使用。</li></ul><hr><h2 id="_5-显式-props-不占-attrs" tabindex="-1">5. 显式 props（不占 attrs） <a class="header-anchor vp-link" href="#_5-显式-props-不占-attrs" aria-label="Permalink to &quot;5. 显式 props（不占 attrs）&quot;">​</a></h2><div class="vp-table"><table><thead><tr><th>Prop</th><th>类型 / 默认</th><th>说明</th></tr></thead><tbody><tr><td><strong><code>modelValue</code></strong></td><td>—</td><td><strong>对外</strong>绑定值。单值：与 EP 一致。<strong>范围 + <code>rangeMerge</code></strong>：<strong><code>string | null</code></strong>（两段由 <strong><code>mergeDelimiter</code></strong> 拼接）。<strong>范围 + 非 merge</strong>：EP 范围形态（一般为 <strong>长度 2 的数组</strong>）。</td></tr><tr><td><strong><code>rangeMerge</code></strong></td><td><strong><code>boolean</code></strong>，默认 <strong><code>false</code></strong></td><td><strong>仅当</strong> <code>is-range</code> / <code>isRange</code> 为 <strong><code>true</code></strong> 时生效；否则无效果。</td></tr><tr><td><strong><code>mergeDelimiter</code></strong></td><td><strong><code>string</code></strong>，默认 <strong><code>&#39;,&#39;</code></strong></td><td><strong>仅用于存储串</strong>的拼接与拆分；<strong>与 EP <code>range-separator</code>（面板「起—止」展示）语义分离</strong>。若传入 <strong><code>null</code></strong>、<strong><code>undefined</code></strong> 或 <strong>空字符串</strong>，<strong>有效分隔符回退为 <code>&#39;,&#39;</code></strong>（与 <strong><code>C7DatePicker</code></strong> 对 <strong><code>mergeDelimiter</code></strong> 的回退规则一致）。</td></tr></tbody></table></div><hr><h2 id="_6-默认-format-valueformat" tabindex="-1">6. 默认 <code>format</code> / <code>valueFormat</code> <a class="header-anchor vp-link" href="#_6-默认-format-valueformat" aria-label="Permalink to &quot;6. 默认 `format` / `valueFormat`&quot;">​</a></h2><ul><li>当 <strong><code>format</code></strong> 未定义，且 <strong><code>valueFormat</code> 与 <code>value-format</code> 均未定义</strong> 时，向 EP 注入 <strong><code>format: &#39;HH:mm:ss&#39;</code></strong>、<strong><code>valueFormat: &#39;HH:mm:ss&#39;</code></strong>（占位符与 EP / dayjs 约定一致即可）。</li><li><strong>任一已传</strong>：不注入，行为与裸 <strong><code>ElTimePicker</code></strong> 一致。</li></ul><p>实现可参考 <strong><code>C7DatePicker</code></strong> 的 <strong><code>pickerAttrs</code> <code>computed</code></strong>：从 <strong><code>attrs</code></strong> 拷贝后删 <strong><code>onUpdate:modelValue</code> 等监听键</strong>，再按需合并默认值。</p><hr><h2 id="_7-范围模式判定" tabindex="-1">7. 范围模式判定 <a class="header-anchor vp-link" href="#_7-范围模式判定" aria-label="Permalink to &quot;7. 范围模式判定&quot;">​</a></h2><p><strong>范围模式</strong>以根上传入的 <strong><code>is-range</code> 或 <code>isRange</code> 为 <code>true</code></strong> 为准（含 Vue 布尔空属性等价为 true 的写法以实现为准，与 <strong><code>C7TimePicker</code></strong> 现实现一致）。<strong>非范围</strong>时：<strong><code>rangeMerge</code> / <code>mergeDelimiter</code></strong> 无效果，<strong><code>outerToInner</code> / <code>innerToOuter</code></strong> 对单值直透传（除清空归一化见第 9 节）。</p><hr><h2 id="_8-outertoinner-外向-→-ep-内向" tabindex="-1">8. <code>outerToInner</code>（外向 → EP 内向） <a class="header-anchor vp-link" href="#_8-outertoinner-外向-→-ep-内向" aria-label="Permalink to &quot;8. `outerToInner`（外向 → EP 内向）&quot;">​</a></h2><p>记 <strong><code>effectiveDelimiter</code></strong>：与 <strong><code>mergeDelimiter</code></strong> 规则一致，空则 <strong><code>&#39;,&#39;</code></strong>。</p><p><strong>非范围</strong>：直接返回 <strong><code>outer</code></strong>，与 <strong><code>C7DatePicker</code></strong> 非范围分支一致（<strong>不</strong>对 <strong><code>&#39;&#39;</code></strong> 做额外归一化，由 EP 处理）。</p><p><strong>范围 + <code>rangeMerge</code>：</strong></p><div class="vp-table"><table><thead><tr><th>外向 <code>outer</code></th><th>内向结果</th></tr></thead><tbody><tr><td><strong><code>null</code> / <code>undefined</code> / <code>&#39;&#39;</code></strong></td><td><strong><code>null</code></strong></td></tr><tr><td><strong><code>string</code></strong></td><td>若不包含 <strong><code>effectiveDelimiter</code></strong> → <strong><code>null</code></strong> + <strong><code>console.warn</code></strong>（键去重，避免刷屏）。否则 <strong><code>split(delim)</code> → 两段 <code>trim</code></strong>：恰好两段且均非空 → <strong><code>[a, b]</code></strong>；否则 <strong><code>null</code> + warn</strong>。</td></tr><tr><td><strong><code>Array</code></strong></td><td>长度 <strong>2</strong> → 原样返回；否则 <strong><code>null</code> + warn</strong>。</td></tr><tr><td><strong>其它类型</strong></td><td><strong><code>null</code> + warn</strong>。</td></tr></tbody></table></div><p><strong>范围 + 非 <code>rangeMerge</code>（与 <code>C7DatePicker</code> 的差异点，已定稿 4A）：</strong></p><ul><li><strong><code>C7DatePicker</code></strong>：只要是 <strong>范围 <code>type</code></strong>，外向为 <strong><code>string</code></strong> 时 <strong>一律</strong>按 <strong><code>effectiveDelimiter</code></strong> 拆成两段数组供 EP 回显（与 <strong><code>rangeMerge</code> 取值无关</strong>；<strong><code>rangeMerge</code> 仅影响 <code>innerToOuter</code> 是否合并回单串</strong>）。</li><li><strong><code>C7TimePicker</code></strong>：<strong>仅接受长度 2 的数组</strong>；外向为 <strong><code>string</code></strong> 时 <strong>不</strong>按存储串拆分 → <strong><code>null</code> + <code>console.warn</code></strong>（避免在「外向应为数组」的契约下静默误解析）。业务若需从合并串回显，<strong>必须</strong> <strong><code>rangeMerge=true</code></strong>（或在上层先拆成数组再传入）。</li></ul><hr><h2 id="_9-innertoouter-ep-内向-→-外向" tabindex="-1">9. <code>innerToOuter</code>（EP 内向 → 外向） <a class="header-anchor vp-link" href="#_9-innertoouter-ep-内向-→-外向" aria-label="Permalink to &quot;9. `innerToOuter`（EP 内向 → 外向）&quot;">​</a></h2><p><strong>非范围</strong>：返回 <strong><code>inner</code></strong>。</p><p><strong>范围</strong>：若 <strong><code>inner == null</code></strong> → 外向 <strong><code>null</code></strong>。若 <strong>非数组</strong> 或 <strong>长度不为 2</strong> → 外向 <strong><code>null</code></strong>（与 <strong><code>C7DatePicker</code></strong> 一致，不额外 warn，避免与 EP 内部瞬时状态打架）。</p><p><strong>范围 + <code>rangeMerge</code>：</strong> 设两段为 <strong><code>a</code></strong>、<strong><code>b</code></strong>（与 <strong><code>C7DatePicker</code></strong> 相同逻辑）：</p><ul><li>若 <strong><code>a == null &amp;&amp; b == null</code></strong> → <strong><code>null</code></strong>；</li><li>否则 <strong><code>String(a 或 &#39;&#39;) + effectiveDelimiter + String(b 或 &#39;&#39;)</code></strong>（<strong><code>null</code> 段以空串参与拼接</strong>，与 <strong><code>C7DatePicker</code></strong> 的 <strong><code>innerToOuter</code></strong> 一致）。</li></ul><p><strong>范围 + 非 <code>rangeMerge</code></strong>：返回 <strong><code>inner</code></strong> 数组。</p><hr><h2 id="_10-事件" tabindex="-1">10. 事件 <a class="header-anchor vp-link" href="#_10-事件" aria-label="Permalink to &quot;10. 事件&quot;">​</a></h2><div class="vp-table"><table><thead><tr><th>事件</th><th>约定</th></tr></thead><tbody><tr><td><strong><code>update:modelValue</code></strong></td><td>载荷为 <strong><code>innerToOuter</code></strong> 后的外向值。</td></tr><tr><td><strong><code>change</code></strong></td><td>载荷与 <strong><code>update:modelValue</code></strong> <strong>同形态</strong>（含清空为 <strong><code>null</code></strong>）。</td></tr><tr><td><strong><code>blur</code> / <code>focus</code></strong></td><td>与 EP 一致，原样 <strong><code>emit</code></strong>。</td></tr></tbody></table></div><hr><h2 id="_11-日志与调试" tabindex="-1">11. 日志与调试 <a class="header-anchor vp-link" href="#_11-日志与调试" aria-label="Permalink to &quot;11. 日志与调试&quot;">​</a></h2><p>非法合并串、非法数组长度、不支持的类型：使用 <strong><code>console.warn</code></strong>，前缀 <strong><code>[C7TimePicker]</code></strong>，并对 <strong><code>warnParseOnce</code></strong> 采用与 <strong><code>C7DatePicker</code></strong> 类似的 <strong>key 去重</strong>，避免 <strong><code>computed</code></strong> 重复触发刷屏。</p><hr><h2 id="_12-测试建议-实现阶段" tabindex="-1">12. 测试建议（实现阶段） <a class="header-anchor vp-link" href="#_12-测试建议-实现阶段" aria-label="Permalink to &quot;12. 测试建议（实现阶段）&quot;">​</a></h2><ol><li><strong>默认格式</strong>：不传 <strong><code>format</code> / <code>value-format</code> / <code>valueFormat</code></strong> 时，行为符合 <strong><code>HH:mm:ss</code></strong> 注入预期。</li><li><strong>范围 + <code>rangeMerge</code></strong>：外向 <strong><code>&quot;08:00:00,18:00:00&quot;</code></strong> 回显；修改后仍为合并串；<strong><code>mergeDelimiter</code></strong> 非逗号时拆拼正确。</li><li><strong>范围 + 非 <code>rangeMerge</code></strong>：二元数组与 EP 一致；<strong>误传合并串</strong> → 内向 <strong><code>null</code></strong> 且 warn（与第 8 节一致）。</li><li><strong>非法合并串 / 非法数组</strong>：内向 <strong><code>null</code></strong>，warn 可观测且不过度重复。</li><li><strong>非范围</strong>：<strong><code>rangeMerge=true</code></strong> 不产生字符串合并。</li><li><strong>与 <code>range-separator</code></strong>：面板展示分隔符与 <strong><code>mergeDelimiter</code></strong> 存储串互不影响。</li></ol><hr><h2 id="_13-范围与非目标" tabindex="-1">13. 范围与非目标 <a class="header-anchor vp-link" href="#_13-范围与非目标" aria-label="Permalink to &quot;13. 范围与非目标&quot;">​</a></h2><ul><li><strong>本期不包含</strong>：日期时间混合选择（由 <strong><code>C7DatePicker</code></strong> 等承担）。</li><li><strong>不修改</strong>：<strong><code>C7DatePicker</code></strong> 源码；本文档 <strong>显式记录</strong> 时间侧与日期侧在 <strong>范围外向 <code>string</code> 解析</strong> 上的差异，避免读者误以为两组件 <strong><code>outerToInner</code> 完全一致</strong>。</li></ul><hr><h2 id="_14-原始需求-·-openspec-·-实现-—-对照-澄清-1b" tabindex="-1">14. 原始需求 · OpenSpec · 实现 — 对照（澄清 1B） <a class="header-anchor vp-link" href="#_14-原始需求-·-openspec-·-实现-—-对照-澄清-1b" aria-label="Permalink to &quot;14. 原始需求 · OpenSpec · 实现 — 对照（澄清 1B）&quot;">​</a></h2><div class="vp-table"><table><thead><tr><th>维度</th><th>原始需求 <code>C7时间选择器.md</code></th><th>OpenSpec <code>openspec/changes/ui-c7-time-picker/specs/...</code></th><th>实现 <code>C7TimePicker/index.vue</code></th></tr></thead><tbody><tr><td>默认格式</td><td><code>HH:mm:ss</code></td><td>未传 format/valueFormat 时注入 <strong><code>HH:mm:ss</code></strong></td><td><strong>一致</strong></td></tr><tr><td>范围 + 合并外向</td><td><code>rangeMerge=true</code> 逗号串等</td><td><code>rangeMerge</code> + <code>mergeDelimiter</code>，拆分/拼接规则</td><td><strong>一致</strong></td></tr><tr><td>范围 + 非合并外向</td><td>「否则输出数组」</td><td><code>rangeMerge=false</code> 时数组；<strong>外向 <code>string</code> 不拆分</strong></td><td><strong>一致</strong></td></tr><tr><td>事件</td><td><code>update:modelValue</code>、<code>change</code>/<code>blur</code>/<code>focus</code></td><td>同设计 + <code>change</code> 与 v-model 同形态</td><td><strong>一致</strong></td></tr><tr><td>与 <code>C7DatePicker</code></td><td>未写细</td><td>Spec 写明 <strong><code>rangeMerge=false</code> 不解析 <code>string</code></strong></td><td><strong>一致</strong>；与 <strong>日期组件实现</strong> 在「范围 + 外向 <code>string</code>」上 <strong>不同</strong>（见第 8 节）</td></tr></tbody></table></div><p><strong>结论</strong>：当前实现与 OpenSpec、原始需求验收口径 <strong>一致</strong>；与 <strong><code>C7DatePicker</code></strong> 的差异为 <strong>已定稿的有意行为</strong>，评审与文档以本文第 8 节为准。</p><hr><h2 id="_15-后续流程" tabindex="-1">15. 后续流程 <a class="header-anchor vp-link" href="#_15-后续流程" aria-label="Permalink to &quot;15. 后续流程&quot;">​</a></h2><p>设计文档经 <strong>你审阅确认无修改</strong> 后，使用 <strong><code>writing-plans</code></strong> 产出可执行实现计划（若实现已全部完成，则计划可退化为「核对测试与文档链接」类条目）。实现完成后按需补充 <strong><code>docs/docs/frontend/components</code></strong> 与 OpenSpec 归档流程（若仓库流程要求）。</p><hr><p><strong>自检（占位 / 矛盾 / 范围）</strong>：无 TBD；第 8 节与第 14 节相互支撑、无「与日期侧相同」的误导表述；范围聚焦 <strong><code>C7TimePicker</code></strong>，不含后端与其它组件改造。</p>',63)])])}const h=e(d,[["render",s]]);export{p as __pageData,h as default};
